function sync(graph){const body=document.querySelector('#analysisPanel .shell-panel-body');if(body&&panel.parentElement!==body)body.prepend(panel);if(activeCorpus&&activeCorpus!==window.ATLAS_DATA.summary.corpus_id)resetContext();activeCorpus=window.ATLAS_DATA.summary.corpus_id;installed=graph;const settings=graph.semantic;kind.value=settings.kind;textScope.value=settings.textScope;support.value=settings.minimumSupport;vocabulary.value=settings.vocabularyLimit;score.value=settings.minimumScore;similarity.value=settings.minimumSimilarity;resolution.value=settings.resolution;cached.checked=!!settings.supplementalText;construction.textContent=method(graph).title+' · '+graph.nodes.length+' '+method(graph).plural+' · '+graph.stats.clusters+' clusters · CPM '+settings.resolution+' · 3 seeded starts · '+(settings.kind==='embeddings'?'cosine ≥'+settings.minimumSimilarity:'source support ≥'+settings.minimumSupport)+'. Citation Auto CPM and connection orders do not apply.';build.disabled=sensitivity.disabled=window.BIBLIOMAP?.active&&window.BIBLIOMAP.canCompute===false;explain();if(graph.semanticSensitivity)renderReport(graph.semanticSensitivity);else panel.querySelector('.semantic-report')?.remove();status.textContent='Completed semantic map for the current pinned source evidence.';}
