import {analysisErrorMessage} from './analysis-errors.mjs';
import {temporalSettings,temporalSupport,publicationYear} from './temporal-series.mjs';
import {burstSettings} from './publication-bursts.mjs';

export function mountTemporalBrowser(){
 if(window.ATLAS_TRIAL_WORKSPACE)return;
 const element=(tag,text='')=>{const node=document.createElement(tag);node.textContent=text;return node;},panel=element('details'),title=element('summary','Time windows & publication activity');panel.id='temporalControls';panel.append(title);
 const form=element('div');form.className='semantic-controls';panel.append(form);
 const field=(labelText,type,value)=>{const label=element('label',labelText),input=element(type==='select'?'select':'input');if(type!=='select')input.type=type;input.value=value;label.append(input);form.append(label);return input;},from=field('From publication year','number',2000),to=field('Through publication year','number',2025),width=field('Window width · years','number',5),step=field('Step · years','number',5),universe=field('Node universe','select');universe.append(new Option('Fixed parent nodes','fixed'),new Option('Reselect within parent scope','changing'));
 const cpm=field('Fixed Leiden CPM','number',.02);cpm.step='any';cpm.min=.000001;const seed=field('Leiden random seed','number',42);seed.min=0;seed.step=1;
 const burstKind=field('Activity feature','select');for(const[value,text]of[['terms','Literal title terms'],['topics','OpenAlex classifier topics'],['references','Cited references in parent scope']])burstKind.append(new Option(text,value));
 const penalty=field('Burst transition penalty','number',1);penalty.min=.05;penalty.max=10;penalty.step=.05;const scale=field('Burst state multiplier','number',2);scale.min=1.1;scale.max=4;scale.step=.1;
 const excludeLabel=element('label'),exclude=element('input');exclude.type='checkbox';exclude.checked=true;excludeLabel.append(exclude,document.createTextNode('Exclude potentially partial retrieval year (latest observed year if date unknown)'));panel.append(excludeLabel);
 panel.append(element('p','Windows rebuild pairwise Leiden evidence from source publication years, not a historical database replay. Fixed parent nodes or within-parent reselection; independent fits, not joint temporal Leiden. Activity uses distinct source documents divided by corpus publication exposure.'));
 const actions=element('div');actions.className='science-actions';panel.append(actions);const status=element('p');status.setAttribute('role','status');panel.append(status);
 const button=(text,action,parent=actions)=>{const node=element('button',text);node.type='button';node.className='secondary';node.onclick=action;parent.append(node);return node;},build=button('Build publication windows',()=>run('temporal-series')),bursts=button('Find publication activity changes',()=>run('publication-bursts')),cancel=button('Cancel',stop);cancel.hidden=true;
 const seriesView=element('div'),burstView=element('div');panel.append(seriesView,burstView);
 const strip=element('section');strip.id='publicationTimeline';strip.className='publication-timeline';strip.hidden=true;strip.setAttribute('aria-label','Completed publication windows');document.querySelector('.map-intro').after(strip);
 let worker,remoteJob,ticket=0,currentSeries,baseSnapshot,activeCorpus,installedGraph;
 function stop(){ticket++;worker?.terminate();worker=null;remoteJob?.cancel();remoteJob=null;cancel.hidden=true;build.disabled=bursts.disabled=!!window.atlasSharedCanvas?.graph()?.temporalSelection||window.BIBLIOMAP?.active&&window.BIBLIOMAP.canCompute===false;status.textContent='Stopped. Previous completed map and saved windows remain available.';}
 function download(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),link=element('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function attach(){const host=document.querySelector('#analysisPanel .shell-panel-body')||document.querySelector('.community-controls');if(panel.parentElement!==host)host.prepend(panel);}
 function sync(graph){if(installedGraph&&installedGraph!==graph&&(worker||remoteJob))stop();attach();const corpus=window.ATLAS_DATA?.summary?.corpus_id;if(activeCorpus!==corpus){activeCorpus=corpus;currentSeries=null;baseSnapshot=null;seriesView.replaceChildren();burstView.replaceChildren();strip.hidden=true;const years=Object.values(window.ATLAS_DATA?.articles||{}).map(publicationYear).filter(year=>year!==null);if(years.length){to.value=Math.max(...years);from.value=Math.max(Math.min(...years),Number(to.value)-29);}}if(installedGraph?._resultId!==graph._resultId)baseSnapshot=null;installedGraph=graph;const footer=document.querySelector('.status-bar>span:last-child'),total=window.ATLAS_DATA?.summary?.source_corpus_size??Object.keys(window.ATLAS_DATA?.articles||{}).length;if(footer)footer.textContent=(graph.temporalSelection?graph.temporal.sourceCount+' window sources of '+total+' pinned sources':total+' pinned source articles')+' · Human validation pending';if(graph.temporalSeries){currentSeries=graph.temporalSeries;const settings=currentSeries.settings;from.value=settings.from;to.value=settings.to;width.value=settings.width;step.value=settings.step;universe.value=settings.universe;cpm.value=settings.resolution;seed.value=settings.seed;renderSeries(graph.temporalSelection?.index??null);}else{currentSeries=null;baseSnapshot=null;seriesView.replaceChildren();strip.hidden=true;}if(graph.burstReport)renderBursts(graph.burstReport);else burstView.replaceChildren();build.disabled=bursts.disabled=!!graph.temporalSelection||window.BIBLIOMAP?.active&&window.BIBLIOMAP.canCompute===false;}
 function local(stage,graph,works,settings,generation){return new Promise((resolve,reject)=>{const activeWorker = worker = new Worker('temporal-worker.js?v=coupling-errors-2');activeWorker.onmessage=event=>{if(generation!==ticket)return;if(event.data.progress){status.textContent=event.data.progress;return;}activeWorker.terminate(); if(worker === activeWorker) worker = null;Object.hasOwn(event.data, 'error') ?reject(Error(analysisErrorMessage(event.data.error))):resolve(event.data.result);};activeWorker.onerror=event=>{activeWorker.terminate(); if(worker === activeWorker) worker = null;reject(Error(analysisErrorMessage(event)));};activeWorker.postMessage({stage,graph,works,settings});});}
 async function run(stage){
  if(window.BIBLIOMAP?.active&&window.BIBLIOMAP.canCompute===false){status.textContent='View-only project. Ask an editor to compute these results.';return;}
  stop();const generation=ticket,canvas=window.atlasSharedCanvas,parent=canvas.graph(),corpus=window.ATLAS_DATA.summary.corpus_id;build.disabled=bursts.disabled=true;cancel.hidden=false;status.textContent='Preparing pinned publication evidence · previous map remains visible.';
  try{if(parent.temporalSelection)throw Error('Return to the full pinned map first. Completed windows are read-only analytical views.');let settings;if(stage==='temporal-series'){temporalSupport(parent);settings=temporalSettings({from:+from.value,to:+to.value,width:+width.value,step:+step.value,universe:universe.value,resolution:+cpm.value,seed:+seed.value,algorithm:parent.clustering?.algorithm==='Leiden CPM'?'leiden':parent.clustering?.algorithm||'leiden'});}else settings=burstSettings({kind:burstKind.value,from:+from.value,to:+to.value,penalty:+penalty.value,scale:+scale.value,excludeLatest:exclude.checked});
   let result;if(window.BIBLIOMAP?.active){remoteJob=window.BIBLIOMAP.stage(parent,stage,settings,message=>{if(generation===ticket)status.textContent=message;});result=await remoteJob.promise;}else{const evidence=await window.ATLAS_EVIDENCE.prepareDataset();if(evidence.sourceCorpusId!==corpus)throw Error('Pinned source evidence changed. Reopen this project.');result=await local(stage,parent,evidence.articles,settings,generation);}
   if(generation!==ticket||canvas.graph()!==parent||window.ATLAS_DATA.summary.corpus_id!==corpus)return;
   if(stage==='temporal-series'){parent.temporalSeries=result;window.ATLAS_DESCRIPTIONS?.sync(parent);currentSeries=result;baseSnapshot=canvas.capture();renderSeries();status.textContent=result.windows.length+' completed windows · select any period to redraw without recomputing.';}else{parent.burstReport=result;renderBursts(result);status.textContent='Activity model '+result.status+' · '+result.coverage.assessedFeatures+'/'+result.coverage.features+' features assessed. The map is unchanged.';}
   window.dispatchEvent(new CustomEvent('bibliomap:time-ready',{detail:parent}));
  }catch(problem){if(generation===ticket)status.textContent='No new result: '+analysisErrorMessage(problem);}finally{if(generation===ticket){cancel.hidden=true;build.disabled=bursts.disabled=!!window.atlasSharedCanvas?.graph()?.temporalSelection||window.BIBLIOMAP?.active&&window.BIBLIOMAP.canCompute===false;remoteJob=null;}}
 }
 function select(index){const canvas=window.atlasSharedCanvas,visible=canvas.graph(),series=visible.temporalSeries||currentSeries;if(!series?.windows[index])return;if(!baseSnapshot||!visible.temporalSelection)baseSnapshot=canvas.capture();const next=structuredClone(series.windows[index].graph);Object.assign(next,{temporalSeries:series,temporalSelection:{index,settings:series.settings},burstReport:visible.burstReport,_resultId:visible._resultId,_projectId:visible._projectId,_analysisKey:visible._analysisKey,_attachments:visible._attachments,sourceCorpusId:visible.sourceCorpusId});window.ATLAS_EVIDENCE.cancelCanvasReliability();if(next.canvasKind==='coupling')window.ATLAS_EVIDENCE.restoreCoupling(next);else canvas.showTemporal(next);sync(canvas.graph());window.dispatchEvent(new CustomEvent('bibliomap:time-ready',{detail:canvas.graph()}));status.textContent='Showing completed '+series.windows[index].from+'–'+series.windows[index].to+' · no new calculation. Group numbers are local to this window.';}
 function fullMap(){const canvas=window.atlasSharedCanvas,visible=canvas.graph(),series=visible.temporalSeries||currentSeries;if(!series)return;if(baseSnapshot&&!baseSnapshot.graph.temporalSelection){canvas.restore(baseSnapshot);canvas.graph().temporalSeries=series;}else{const parent=structuredClone(series.parentGraph);Object.assign(parent,{temporalSeries:series,burstReport:visible.burstReport,_resultId:visible._resultId,_projectId:visible._projectId,_analysisKey:visible._analysisKey,_attachments:visible._attachments,sourceCorpusId:visible.sourceCorpusId});parent.appliedSettings||={settings:{label:'Full pinned parent analysis'}};if(parent.canvasKind==='coupling')window.ATLAS_EVIDENCE.restoreCoupling(parent);else canvas.showTemporal(parent);}sync(canvas.graph());status.textContent='Full pinned map restored · completed reports retained · no new calculation.';window.dispatchEvent(new CustomEvent('bibliomap:time-ready',{detail:canvas.graph()}));}
 function renderSeries(index=null){strip.replaceChildren();strip.hidden=false;button('Full pinned map',fullMap,strip);for(const[windowIndex,period]of currentSeries.windows.entries()){const control=button(period.from+'–'+period.to+' · '+period.sourceCount,()=>select(windowIndex),strip);control.setAttribute('aria-pressed',String(index===windowIndex));control.title=period.sourceCount+' distinct source publications · '+period.graph.stats.clusters+' local groups'+(period.truncatedBoundary?' · truncated boundary window':'')+(period.potentiallyPartial?' · potentially partial latest period':'');}
  seriesView.replaceChildren(element('p',currentSeries.coverage.knownYear+'/'+currentSeries.coverage.sources+' sources have publication years; '+currentSeries.coverage.unknownYear+' unknown, '+currentSeries.coverage.outsideBoundary+' outside boundaries; '+currentSeries.windows.filter(window=>window.truncatedBoundary).length+' truncated boundary windows. '+currentSeries.settings.universe+' parent universe. Evidence date: '+(currentSeries.evidenceDate||currentSeries.evidence?.retrievedAt||'unknown')+'. '+(currentSeries.latestPeriod?.warning||(currentSeries.evidence?.retrievedAt?'The retrieval year and later publication years may be partial; stored windows include them explicitly.':'Latest-period completeness is unknown.'))+' '+currentSeries.limitation));button('Export complete windows & memberships',()=>download(currentSeries,'bibliomap-publication-windows.json'),seriesView);
  const transitions=element('details');transitions.append(element('summary','Community overlaps, split & merge candidates'));for(const transition of currentSeries.transitions){const section=element('details');section.append(element('summary',currentSeries.windows[transition.fromWindow].from+' → '+currentSeries.windows[transition.toWindow].from+' · '+transition.commonAssignedBoth+'/'+transition.commonIds.length+' common nodes assigned both · '+transition.splits.length+' split / '+transition.merges.length+' merge candidates'));section.append(element('p',transition.firstOnly.length+' leave node universe; '+transition.secondOnly.length+' enter; '+transition.firstUnassigned+'/'+transition.secondUnassigned+' common nodes unassigned. '+transition.interpretation));for(const overlap of transition.overlaps.slice(0,30)){const row=element('details');row.append(element('summary','Group '+overlap.from+' → '+overlap.to+' · '+overlap.count+' members · '+(100*overlap.fromShare).toFixed(0)+'% earlier / '+(100*overlap.toShare).toFixed(0)+'% later'));row.append(element('p',overlap.members.join(', ')));for(const id of overlap.members.slice(0,20)){const member=currentSeries.windows[transition.toWindow].graph.nodes.find(node=>node.id===id);button('Inspect '+(member?.label||member?.title||id),()=>{select(transition.toWindow);window.atlasInspectReference(id);},row);}if(overlap.members.length>20)row.append(element('p','First 20 member inspection buttons; all IDs are retained above and in export.'));section.append(row);}if(transition.overlaps.length>30)section.append(element('p','First 30 overlaps shown; all memberships/unmatched groups are in the complete export.'));transitions.append(section);}seriesView.append(transitions);
 }
 function renderBursts(report){burstView.replaceChildren(element('h3','Publication activity · '+report.status),element('p',report.coverage.knownYear+'/'+report.coverage.sources+' dated sources · '+report.coverage.unknownYear+' unknown · '+report.coverage.exposedPeriods+' exposed periods. '+report.latestPeriod.warning),element('p',report.baseline),element('p',report.limitation));button('Export activity, counts & sensitivity',()=>download(report,'bibliomap-publication-activity.json'),burstView);const methodology=element('details');methodology.append(element('summary','Model and exposure coverage'),element('p',report.method));const reference=element('a','Kleinberg · original batched-document model');reference.href=report.reference;reference.target='_blank';reference.rel='noopener';methodology.append(reference);for(const period of report.periods)methodology.append(element('p',period.from+'–'+period.to+' · '+period.exposure+' usable model exposure of '+period.allSourceExposure+' corpus sources · '+period.availableMetadata+' with observed feature metadata / '+period.unavailableMetadata+' without · '+period.status));burstView.append(methodology);
  for(const feature of report.features.slice(0,20)){const row=element('details');row.append(element('summary',feature.label+' · '+feature.fit.intervals.length+' elevated-state intervals · '+feature.totalSources+' sources'));row.append(element('p',feature.fit.reason||'Whole-span observed share '+(100*feature.fit.baseRate).toFixed(2)+'% · '+feature.unknownYearSupport+' supporting sources have unknown years.'));for(const period of feature.periods)row.append(element('p',period.from+'–'+period.to+': '+period.count+'/'+period.exposure+' · '+(period.rate===null?'no exposure':(100*period.rate).toFixed(1)+'%')+' · state '+(feature.fit.states[feature.periods.indexOf(period)]??'not assessed')+(period.baselineFlag?' · descriptive 2×share baseline flag':'')));for(const interval of feature.fit.intervals)row.append(element('p','Elevated state '+interval.level+' · '+interval.from+'–'+interval.to+' · '+interval.sourceCount+' distinct source publications'));const sources=element('details');sources.append(element('summary','Inspect supporting source articles'));const articles=window.ATLAS_DATA?.articles||{};for(const id of feature.sourceIds.slice(0,50)){const article=articles[id]||{},source=element('details');source.append(element('summary',article.title||article.display_name||id),element('p',(article.year||article.publication_year||'Publication year unknown')+' · '+id));if(id.startsWith('https://openalex.org/W')){const link=element('a','Open source record');link.href=id;link.target='_blank';link.rel='noopener';source.append(link);}sources.append(source);}if(feature.sourceIds.length>50)sources.append(element('p','First 50 sources shown; complete IDs are exported.'));row.append(sources);burstView.append(row);}if(report.features.length>20)burstView.append(element('p','First 20 ranked features shown; all counts/source IDs are exported.'));const sensitivity=element('details');sensitivity.append(element('summary','Parameter, binning, partial-year & metadata sensitivity'));for(const check of report.sensitivity)sensitivity.append(element('p','Penalty '+check.settings.penalty+' · multiplier '+check.settings.scale+' · '+check.settings.width+'-year bins · '+(check.settings.excludeLatest?'exclude':'include')+' partial year · '+(check.settings.denominator||'all-source')+' denominator · '+check.assessedFeatures+' features assessed / '+check.features.filter(feature=>feature.intervals.length).length+' with elevated states.'));burstView.append(sensitivity);
 }
 form.addEventListener('input',()=>{if(worker||remoteJob)stop();});form.addEventListener('change',()=>{if(worker||remoteJob)stop();});exclude.onchange=()=>{if(worker||remoteJob)stop();};
 window.ATLAS_TEMPORAL={sync,select,stop,open:()=>{attach();panel.open=true;window.atlasWorkspaceShell?.show('analysis');window.atlasWorkspaceShell?.reveal(panel);}};
 attach();const open=button('Time windows & activity',()=>window.ATLAS_TEMPORAL.open(),document.querySelector('.workspace-tabs'));open.id='workspace-time';open.setAttribute('aria-label','Open time windows and publication activity controls');
 window.addEventListener('bibliomap:selection-changed',()=>{stop();currentSeries=null;baseSnapshot=null;strip.hidden=true;});document.addEventListener('click',event=>{if(event.target.closest('.workspace-tabs button')&&event.target.id!=='workspace-time')stop();});document.addEventListener('DOMContentLoaded',()=>sync(window.atlasSharedCanvas.graph()),{once:true});
}
